private func updateExteraSendAsGestures() {
    let enabled = ExteraPreferences.standard.value(for: ExteraSettings.hideSendAsPeer)
        && self.presentationInterfaceState?.sendAsPeers?.isEmpty == false
        && self.presentationInterfaceState?.editMessageState == nil
    for (item, button) in self.accessoryItemButtons {
        let isInput: Bool
        if case .input = item { isInput = true } else { isInput = false }
        var gestures = (button.gestureRecognizers ?? []).filter { $0.name == "ExteraSendAsLongPress" }
        if isInput && gestures.isEmpty {
            let gesture = UILongPressGestureRecognizer(target: self, action: #selector(self.exteraSendAsLongPressed(_:)))
            gesture.name = "ExteraSendAsLongPress"
            button.addGestureRecognizer(gesture)
            gestures.append(gesture)
        }
        for gesture in gestures { gesture.isEnabled = enabled && isInput }
    }
}

@objc private func exteraSendAsLongPressed(_ gesture: UILongPressGestureRecognizer) {
    guard gesture.state == .began,
          ExteraPreferences.standard.value(for: ExteraSettings.hideSendAsPeer),
          let state = self.presentationInterfaceState, state.editMessageState == nil,
          state.sendAsPeers?.isEmpty == false, let button = gesture.view,
          let current = self.accessoryItemButtons.first(where: { $0.1 === button }),
          case .input = current.0 else { return }
    if self.exteraSendAsReferenceNode.supernode == nil {
        self.exteraSendAsReferenceNode.isUserInteractionEnabled = false
        self.addSubnode(self.exteraSendAsReferenceNode)
    }
    self.exteraSendAsReferenceNode.frame = self.view.convert(button.bounds, from: button)
    self.interfaceInteraction?.openSendAsPeer(self.exteraSendAsReferenceNode, nil)
}

